{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "The closest-scoring analogue, [11C]MPEPy, is directly shown by PET to cross the BBB in rodents, although it is a P-gp efflux substrate; this supports meaningful CNS access for the similarly sized alkyne-pyridine query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Basimglurant, a fluorophenyl-substituted heteroaryl alkyne mGlu5 modulator, has a brain/plasma ratio of 2-3 in preclinical studies, demonstrating good BBB permeability and supporting a pass for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "RWJ-67657, which shares the fluorophenyl/alkyne/pyridine motif, achieved a 96.3% reduction in brain parasite burden in mice, indicating that the compound reaches therapeutic brain concentrations.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "The only negative record, [18F]MPPF, is a larger, more polar piperazine-amide P-gp substrate with low brain uptake; its structural dissimilarity and efflux liability make it a weak contradictory transfer to the small neutral query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Pass: the query is a small, lipophilic, largely neutral fused heteroaromatic alkyne-pyridine with high passive BBB plausibility, and multiple directly measured CNS-penetrant analogues sharing the alkyne-pyridine/fluorophenyl motif support meaningful brain access; the single negative analogue is structurally dissimilar and efflux-dominated.",
  "evidence_gaps": [
    "No direct experimental brain or plasma exposure data are available for the query molecule.",
    "All analogue Morgan similarities are low (<0.3), limiting quantitative transferability.",
    "The query's own efflux-transporter liability has not been directly measured.",
    "Metabolic stability of the alkyne linker in vivo is unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

